use super::*;
use crate::pet_runtime::{admission_tests::{Fixture,budget,descriptor},admission::Review,authority::Authority,authority_tests::root,lease_controller::{Controller,Pending,Owned},store::nonce};
use std::sync::Arc;
use crate::pet_capabilities::{Snapshot,Availability,Reason};
struct Case{_f:Fixture,_pending:Pending,_owned:Owned,goal:Record,lease:Lease,capture:NativeProjection}
impl Case{
 fn new(provider:&str)->Self{
  let f=Fixture::new();let a=Authority::ensure(&root(&f)).unwrap();let goal=f.goal(provider);let config=crate::pet_config::defaults();let mut settings=Settings::default();settings.chat_models.insert(provider.into(),"fixture-free".into());settings.ollama_url="http://127.0.0.1:11434".into();
  let revision=policy_revision(&config,&settings,&goal).unwrap();let observation=|g:&Record,now|Evidence::observe(g,&descriptor(g,now),revision.clone(),now,false,false).unwrap();
  let approved=Review::prepare(&goal,observation(&goal,100_002),budget(),"queue".into(),nonce().unwrap(),100_002).unwrap().approve(&goal,observation(&goal,100_003),100_003).unwrap();let cert=a.certify(&approved,&goal,100_004).unwrap();let queued=f.store().enqueue_certified(&cert,100_005).unwrap().record;
  let controller=Controller::new().unwrap();let main=crate::chat::Chat::persistent(f.path.join("live-main.json"));let pending=controller.prepare(&queued,&root(&f),&f.path.join("contexts"),&main,&observation(&queued,100_006),"claim".into(),100_006,Arc::new(|_,_,_|Validity::Current)).unwrap();let(receipt,owned)=pending.claim(&f.store(),&a,&observation(&queued,100_007),100_007).unwrap();let owned=owned.unwrap();let lease=owned.lease().clone();let goal=receipt.record;
  let capture=NativeProjection{snapshot:Snapshot{schema_version:1,revision:"test-capture".into(),observed_at:100_008,configuration_available:true,pets:vec![descriptor(&goal,100_008)]},configuration:Some(config),settings};
  Self{_f:f,_pending:pending,_owned:owned,goal,lease,capture}
 }
 fn valid(&self,mode:Validation,now:u64)->Validity{evaluate(&self.goal,&self.lease,&self.capture,mode,now)}
 fn descriptor(&mut self)->&mut Descriptor{&mut self.capture.snapshot.pets[0]}
}
#[test]fn genuine_readiness_is_required_for_new_effects_in_every_llm_and_service_owner(){for owner in ["codex","copilot","antigravity","ollama","integration_notion"]{let case=Case::new(owner);assert_eq!(case.valid(Validation::FreshEffect,100_009),Validity::Current);assert_eq!(case.valid(Validation::InFlightPolicy,100_009),Validity::Current);}}
#[test]fn actual_observation_age_over_fifteen_seconds_blocks_new_effects_without_revoking_existing_io(){let case=Case::new("ollama");assert_eq!(case.valid(Validation::FreshEffect,116_000),Validity::Unknown);assert_eq!(case.valid(Validation::InFlightPolicy,116_000),Validity::Current);}
#[test]fn stale_unknown_readiness_never_becomes_a_ready_descriptor(){let mut case=Case::new("ollama");let cap=&mut case.descriptor().capabilities[0];cap.availability=Availability::Unknown;cap.reason=Some(Reason::StaleObservation);cap.observed_at=None;cap.expires_at=None;assert_eq!(case.valid(Validation::FreshEffect,100_009),Validity::Unknown);assert_eq!(case.valid(Validation::InFlightPolicy,100_009),Validity::Current);assert_eq!(case.capture.snapshot.pets[0].capabilities[0].availability,Availability::Unknown);}
#[test]fn model_or_endpoint_policy_change_blocks_both_phases(){for setting in ["model","endpoint"]{let mut case=Case::new("ollama");if setting=="model"{case.capture.settings.chat_models.insert("ollama".into(),"replacement".into());}else{case.capture.settings.ollama_url="http://127.0.0.1:12345".into();}assert_eq!(case.valid(Validation::FreshEffect,100_009),Validity::Changed);assert_eq!(case.valid(Validation::InFlightPolicy,100_009),Validity::Changed);}}
#[test]fn pet_configuration_and_permissions_revision_is_still_checked_during_io(){let mut case=Case::new("ollama");let pet=case.capture.configuration.as_mut().unwrap().pets.get_mut("ai_ollama").unwrap();let permissions=pet.permissions.get_or_insert_with(Default::default);permissions.open_apps=!permissions.open_apps;assert_eq!(case.valid(Validation::InFlightPolicy,100_009),Validity::Changed);assert_eq!(case.valid(Validation::FreshEffect,100_009),Validity::Changed);}
#[test]fn provider_model_binding_or_inactive_lifecycle_cannot_continue_by_ignoring_ttl(){for change in ["model","provider","inactive","pet","adapter"]{let mut case=Case::new("ollama");let d=case.descriptor();match change{"model"=>d.binding.model=Some("other".into()),"provider"=>d.binding.provider=Some("codex".into()),"inactive"=>d.lifecycle=Lifecycle::Inactive,"pet"=>d.pet_id="agent_codex".into(),_=>d.binding.adapter=Some("codex")};assert_eq!(case.valid(Validation::InFlightPolicy,100_009),Validity::Changed);}}
#[test]fn missing_configuration_is_unknown_not_an_inferred_permission(){let mut case=Case::new("ollama");case.capture.configuration=None;assert_eq!(case.valid(Validation::InFlightPolicy,100_009),Validity::Unknown);assert_eq!(case.valid(Validation::FreshEffect,100_009),Validity::Unknown);}
#[test]fn stopped_goal_or_changed_lease_context_intent_is_not_a_current_operation(){for change in ["stop","lease","context","intent"]{let mut case=Case::new("ollama");match change{"stop"=>case.goal.state=State::Stopping,"lease"=>case.goal.admissions[0].lease.as_mut().unwrap().id=nonce().unwrap(),"context"=>case.goal.execution_context.as_mut().unwrap().conversation_id="different".into(),_=>case.goal.spec.intent="replacement intent".into()};assert_eq!(case.valid(Validation::InFlightPolicy,100_009),Validity::Changed);}}
#[test]fn deadline_and_backwards_observation_are_not_ignored_with_stale_readiness(){let case=Case::new("ollama");assert_eq!(case.valid(Validation::InFlightPolicy,200_000),Validity::Changed);assert_eq!(case.valid(Validation::InFlightPolicy,100_001),Validity::Changed);}
#[test]fn unavailable_projection_cannot_authorize_a_current_operation(){let mut case=Case::new("ollama");case.descriptor().configuration_available=false;assert_eq!(case.valid(Validation::InFlightPolicy,100_009),Validity::Unknown);}
